private val coverPrefetchMutex = Mutex()
private val coverResolvedMediaIds: MutableSet<Long> = java.util.concurrent.ConcurrentHashMap.newKeySet<Long>()
@Volatile private var desktopCoverCatalogGeneration: Long = 0L

